#!/usr/bin/env python3
"""Generate the Homebrew formula for the tickertape CLI from a GitHub release's SHA256SUMS."""

import argparse
import os
from pathlib import Path
import re

import release


REPOSITORY = "https://github.com/thomas0903/tickertape"
# (Homebrew OS block, Homebrew CPU block, release target). Linux uses the static musl archives, as cargo-binstall does.
PLATFORMS = (
    ("on_macos", "on_arm", "aarch64-apple-darwin"),
    ("on_macos", "on_intel", "x86_64-apple-darwin"),
    ("on_linux", "on_arm", release.LINUX_INSTALL_TARGETS["aarch64-unknown-linux-gnu"]),
    ("on_linux", "on_intel", release.LINUX_INSTALL_TARGETS["x86_64-unknown-linux-gnu"]),
)


def parse_checksums(text):
    """Map file names to SHA-256 digests from a `sha256sum` style file."""
    checksums = {}
    for line in text.splitlines():
        match = re.fullmatch(r"([0-9a-f]{64})  (\S+)", line)
        if match is None:
            raise ValueError(f"malformed SHA256SUMS line: {line!r}")
        checksums[match.group(2)] = match.group(1)
    return checksums


def formula(tag, checksums):
    release.version_for_tag(tag)
    blocks = {}
    for os_block, cpu_block, target in PLATFORMS:
        name = f"{release.archive_stem(tag, target)}.tar.gz"
        if name not in checksums:
            raise ValueError(f"SHA256SUMS has no entry for {name}")
        blocks.setdefault(os_block, []).append(
            f"    {cpu_block} do\n"
            f'      url "{REPOSITORY}/releases/download/{tag}/{name}"\n'
            f'      sha256 "{checksums[name]}"\n'
            f"    end\n")
    platforms = "\n".join(f"  {os_block} do\n" + "".join(cpu_blocks) + "  end\n"
                          for os_block, cpu_blocks in blocks.items())
    return f'''# Generated by .github/scripts/homebrew.py in thomas0903/tickertape for {tag}; do not edit by hand.
class Tickertape < Formula
  desc "Tail, inspect, verify, export and archive tickertape journals"
  homepage "{REPOSITORY}"
  license any_of: ["MIT", "Apache-2.0"]

{platforms}
  def install
    bin.install "tickertape"
  end

  test do
    assert_equal "tickertape #{{version}}", shell_output("#{{bin}}/tickertape --version").strip
    output = shell_output("#{{bin}}/tickertape verify #{{testpath}}/missing 2>&1", 1)
    assert_match "No such file or directory", output
  end
end
'''


def formula_version(text):
    # Homebrew scans the version from the URLs; an explicit `version` line fails `brew audit --strict`.
    match = re.search(r"/releases/download/v([0-9]+)\.([0-9]+)\.([0-9]+)/", text)
    return None if match is None else tuple(int(part) for part in match.groups())


def should_write(existing, tag):
    """Never replace a formula for a newer version (a backfill of an older tag must not downgrade the tap)."""
    if existing is None:
        return True
    current = formula_version(existing)
    wanted = tuple(int(part) for part in release.version_for_tag(tag).split("."))
    return current is None or current <= wanted


def generate(args):
    text = formula(args.tag, parse_checksums(args.checksums.read_text()))
    existing = args.output.read_text() if args.output.exists() else None
    current = should_write(existing, args.tag)
    if current:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(text)
        print(f"wrote {args.output} for {args.tag}")
    else:
        print(f"{args.output} is for a newer version; keeping it")
    if "GITHUB_OUTPUT" in os.environ:
        with Path(os.environ["GITHUB_OUTPUT"]).open("a") as file:
            file.write(f"current={str(current).lower()}\n")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--tag", required=True)
    parser.add_argument("--checksums", type=Path, required=True, help="SHA256SUMS from the GitHub release")
    parser.add_argument("--output", type=Path, required=True, help="Formula/tickertape.rb in a tap checkout")
    generate(parser.parse_args())


if __name__ == "__main__":
    main()
